import { router } from 'expo-router';
import { useState } from 'react';
import { FlatList, Pressable, View } from 'react-native';
import { AppModal } from '../../../components/app-modal';
import { AppText, Button } from '../../../design-system/primitives';
import { useTheme } from '../../../design-system/theme';
import notices from '../../../legal/third-party.json';

type Notice = { n: string; v: string; l: string; t: number };

// Open-source software included in the app, with each license text (generated by scripts/third-party-notices.mjs).
export function LicensesScreen() {
  const { colors } = useTheme();
  const [open, setOpen] = useState<Notice | null>(null);
  const packages = notices.packages as Notice[];
  return <View style={{ flex: 1 }}>
    <FlatList data={packages} keyExtractor={item => `${item.n}@${item.v}`} contentContainerStyle={{ padding: 24, maxWidth: 620, width: '100%', alignSelf: 'center' }}
      ListHeaderComponent={<View style={{ gap: 8, paddingBottom: 12 }}>
        <View style={{ alignSelf: 'flex-start' }}><Button label="Back to Settings" icon="back" iconOnly variant="quiet" onPress={() => router.replace('/settings')} /></View>
        <AppText accessibilityRole="header" size={26} weight="600">Open-source licenses</AppText>
        <AppText size={13} tone="secondary">{`Owllowance is built with ${packages.length} open-source packages. Thank you to their authors. Tap one to read its license.`}</AppText>
      </View>}
      renderItem={({ item }) => <Pressable accessibilityRole="button" accessibilityLabel={`${item.n} license`} onPress={() => setOpen(item)}
        style={({ pressed }) => ({ paddingVertical: 12, borderBottomWidth: 1, borderColor: colors.border, opacity: pressed ? 0.7 : 1 })}>
        <AppText size={14} weight="500">{item.n}</AppText>
        <AppText size={12} tone="secondary">{`${item.v} · ${item.l}`}</AppText>
      </Pressable>} />
    {open ? <AppModal title={open.n} visible onClose={() => setOpen(null)}>
      <AppText size={12} tone="secondary">{`${open.v} · ${open.l}`}</AppText>
      <AppText size={12} style={{ fontFamily: 'monospace' }}>{open.t >= 0 ? notices.texts[open.t] : `Licensed under ${open.l}. No license file was included in the package.`}</AppText>
      <Button label="Close" variant="quiet" onPress={() => setOpen(null)} />
    </AppModal> : null}
  </View>;
}
